async function changeLevel(cat: CategoryGroup, value: string) {
  if (cat.evalLevel === value) return
  const f = form.value
  if (!f) return
  uni.showModal({
    title: '修改评价等级',
    content: '修改后该类考评内容将按新等级重新加载，已录入的得分、说明与图片将被清空，是否继续？',
    success: async res => {
      if (!res.confirm || form.value !== f) return
      if (isLocalDraft.value) {
        // 本地草稿未落库：按新等级重新发起一次（不建单），取回新题目；
        // 仅替换被改类别 + 联动汇总字段，其余四类与表单级内容保持原样。
        try {
          const grades: Record<string, string> = {
            gradeComprehensiveLevel: f.categoryList[0]?.evalLevel,
            gradeFacilityLevel: f.categoryList[1]?.evalLevel,
            gradeOrderLevel: f.categoryList[2]?.evalLevel,
            gradeCleanLevel: f.categoryList[3]?.evalLevel,
            gradeGreeningLevel: f.categoryList[4]?.evalLevel,
          }
          const gf = gradeFieldByServiceType[cat.serviceType]
          if (gf) grades[gf] = value
          const fresh = await store.startCheck({
            complexId: f.complexId, checkType: f.checkType, checkTime: f.checkTime,
            ...grades,
          })
          const newCat = fresh.categoryList.find(c => c.serviceType === cat.serviceType)
          const idx = form.value.categoryList.findIndex(c => c.serviceType === cat.serviceType)
          if (newCat && idx !== -1) form.value.categoryList.splice(idx, 1, newCat)
          for (const key of ['evalLevel', 'evalLevelName', 'checkFrequencyName',
            'gradeComprehensiveLevel', 'gradeFacilityLevel', 'gradeOrderLevel', 'gradeCleanLevel', 'gradeGreeningLevel'] as const) {
            ;(form.value as unknown as Record<string, unknown>)[key] = (fresh as unknown as Record<string, unknown>)[key]
          }
          recalc()
          persistDraft()
        } catch (cause) { toastError(cause, '修改评价等级失败，请重试') }
      } else {
        // 已落库草稿：改等级字段后走 save+load，后端/接口按新等级重取题目
        cat.evalLevel = value
        cat.evalLevelName = evalLevelOptions.find(o => o.value === value)?.name ?? value
        for (const proj of cat.projectList) for (const it of proj.itemList) { it.itemScore = null; it.isNotApplicable = '0'; it.remark = ''; it.images = ''; photoMap[it.checkItemId] = [] }
        cat.checkedCount = 0; cat.finished = false
        await save(); await load()
      }
    },
  })
}
